function add(a, b) {
  return a + b;
}

console.log(add(2, 3)); // 5

console.log(greetDeclared()); // "Hi!" — works, because function declarations are hoisted

function greetDeclared() {
  return "Hi!";
}

const greetExpression = function () {
  return "Hello!";
};

console.log(greetExpression()); // "Hello!" — works, but only after this line has run

const user = {
  name: "Ana",
  greet() {
    return `Hi, I'm ${this.name}`;
  },
};

console.log(user.greet()); // "Hi, I'm Ana"

const counter = {
  count: 0,
  incrementWithArrow() {
    return () => {
      this.count++; // the arrow function keeps "this" from incrementWithArrow
    };
  },
};

const addOne = counter.incrementWithArrow();
addOne();
addOne();
console.log(counter.count); // 2

function introduce(greeting) {
  return `${greeting}, I am ${this.name}`;
}

const user = { name: "Ana" };

console.log(introduce.call(user, "Hi"));       // "Hi, I am Ana"
console.log(introduce.apply(user, ["Hello"])); // "Hello, I am Ana"

const boundIntroduce = introduce.bind(user);
console.log(boundIntroduce("Hey")); // "Hey, I am Ana"

