function sumAll() {
  const nums = Array.from(arguments);
  return nums.reduce((total, n) => total + n, 0);
}

console.log(sumAll(1, 2, 3));       // 6
console.log(sumAll(10, 20, 30, 40)); // 100

function greet(name = "friend") {
  return `Hello, ${name}!`;
}

console.log(greet());      // "Hello, friend!"
console.log(greet("Ana")); // "Hello, Ana!"

function createUser(name, age) {
  age = age ?? 18; // use 18 if age is null or undefined
  return { name, age };
}

console.log(createUser("Ana", 30)); // { name: 'Ana', age: 30 }
console.log(createUser("Leo"));     // { name: 'Leo', age: 18 }

function processNumbers(numbers, callback) {
  for (const n of numbers) {
    callback(n);
  }
}

processNumbers([1, 2, 3], function (n) {
  console.log(n * n);
});
// 1
// 4
// 9

// Before: the same calculation is repeated
const priceA = 100 - 100 * 0.1;
const priceB = 50 - 50 * 0.1;
console.log(priceA, priceB); // 90 45

// After: the calculation is moved into one function
function applyDiscount(price, discount) {
  return price - price * discount;
}
console.log(applyDiscount(100, 0.1), applyDiscount(50, 0.1)); // 90 45

