function Person(name) {
  this.name = name;
}

Person.prototype.greet = function () {
  return `Hi, I'm ${this.name}`;
};

const ana = new Person("Ana");
const leo = new Person("Leo");

console.log(ana.greet()); // "Hi, I'm Ana"
console.log(leo.greet()); // "Hi, I'm Leo"
console.log(ana.greet === leo.greet); // true (both share the same function)

function Person(name, age) {
  this.name = name;
  this.age = age;
}

const ana = new Person("Ana", 28);
console.log(ana.name, ana.age);     // "Ana" 28
console.log(ana instanceof Person); // true

const counter = {
  count: 0,
  increment() {
    this.count++;
    return this.count;
  },
};

console.log(counter.increment()); // 1
console.log(counter.increment()); // 2

class Animal {}
class Dog extends Animal {}

const rex = new Dog();

console.log(rex instanceof Dog);    // true
console.log(rex instanceof Animal); // true
console.log(rex instanceof Array);  // false

const result = (function () {
  const secret = 42;
  return secret * 2;
})();

console.log(result);        // 84
console.log(typeof secret); // "undefined" (secret stayed private inside the IIFE)

