assignment.solution:
function averageScore(name, ...scores) {
  const total = scores.reduce((sum, s) => sum + s, 0);
  return `${name}: ${total / scores.length}`;
}

console.log(averageScore("Ana", 80, 90, 100)); // "Ana: 90"
